    ap_CS_fsm_assign_proc : process(ap_clk)
    begin
        if (ap_clk'event and ap_clk =  '1') then
            if (ap_rst_n_inv = '1') then
                ap_CS_fsm <= ap_ST_fsm_state1;
            else
                ap_CS_fsm <= ap_NS_fsm;
            end if;
        end if;
    end process;


    grp_nn_marshal_handle_transaction_fu_66_ap_start_reg_assign_proc : process(ap_clk)
    begin
        if (ap_clk'event and ap_clk =  '1') then
            if (ap_rst_n_inv = '1') then
                grp_nn_marshal_handle_transaction_fu_66_ap_start_reg <= ap_const_logic_0;
            else
                if ((ap_const_logic_1 = ap_CS_fsm_state2)) then 
                    grp_nn_marshal_handle_transaction_fu_66_ap_start_reg <= ap_const_logic_1;
                elsif ((grp_nn_marshal_handle_transaction_fu_66_ap_ready = ap_const_logic_1)) then 
                    grp_nn_marshal_handle_transaction_fu_66_ap_start_reg <= ap_const_logic_0;
                end if; 
            end if;
        end if;
    end process;


    ap_NS_fsm_assign_proc : process (grp_nn_marshal_handle_transaction_fu_66_ap_done, ap_CS_fsm, ap_CS_fsm_state3)
    begin
        case ap_CS_fsm is
            when ap_ST_fsm_state1 => 
                ap_NS_fsm <= ap_ST_fsm_state2;
            when ap_ST_fsm_state2 => 
                ap_NS_fsm <= ap_ST_fsm_state3;
            when ap_ST_fsm_state3 => 
                if (((grp_nn_marshal_handle_transaction_fu_66_ap_done = ap_const_logic_1) and (ap_const_logic_1 = ap_CS_fsm_state3))) then
                    ap_NS_fsm <= ap_ST_fsm_state2;
                else
                    ap_NS_fsm <= ap_ST_fsm_state3;
                end if;
            when others =>  
                ap_NS_fsm <= "XXX";
        end case;
    end process;
    ap_CS_fsm_state2 <= ap_CS_fsm(1);
    ap_CS_fsm_state3 <= ap_CS_fsm(2);

    ap_rst_n_inv_assign_proc : process(ap_rst_n)
    begin
                ap_rst_n_inv <= not(ap_rst_n);
    end process;

    gate_req_TREADY <= regslice_both_gate_req_V_data_V_U_ack_in;

    gate_req_TREADY_int_regslice_assign_proc : process(grp_nn_marshal_handle_transaction_fu_66_gate_req_TREADY, ap_CS_fsm_state3)
    begin
        if ((ap_const_logic_1 = ap_CS_fsm_state3)) then 
            gate_req_TREADY_int_regslice <= grp_nn_marshal_handle_transaction_fu_66_gate_req_TREADY;
        else 
            gate_req_TREADY_int_regslice <= ap_const_logic_0;
        end if; 
    end process;

    gate_resp_TVALID <= regslice_both_gate_resp_V_data_V_U_vld_out;
    grp_nn_marshal_handle_transaction_fu_66_ap_start <= grp_nn_marshal_handle_transaction_fu_66_ap_start_reg;
    grp_nn_marshal_handle_transaction_fu_66_gate_resp_TREADY <= (gate_resp_TREADY_int_regslice and ap_CS_fsm_state3);
    grp_nn_marshal_handle_transaction_fu_66_nn_req_TREADY <= (nn_req_TREADY_int_regslice and ap_CS_fsm_state3);
    nn_req_TVALID <= regslice_both_nn_req_V_data_V_U_vld_out;
    nn_resp_TREADY <= regslice_both_nn_resp_V_data_V_U_ack_in;

    nn_resp_TREADY_int_regslice_assign_proc : process(grp_nn_marshal_handle_transaction_fu_66_nn_resp_TREADY, ap_CS_fsm_state3)
    begin
        if ((ap_const_logic_1 = ap_CS_fsm_state3)) then 
            nn_resp_TREADY_int_regslice <= grp_nn_marshal_handle_transaction_fu_66_nn_resp_TREADY;
        else 
            nn_resp_TREADY_int_regslice <= ap_const_logic_0;
        end if; 
    end process;

